export const ACCOUNT_CSS = '\n.mp-account-window{\n  --bg:var(--mp-night);--surface:var(--mp-night);--surface-2:var(--mp-surface);\n  --surface-3:var(--mp-raised);--border:var(--mp-line);--border-strong:var(--mp-line-strong);\n  --text:var(--mp-text);--text-2:var(--mp-text-2);--muted:var(--mp-text-3);\n  --accent:var(--mp-violet-deep);--accent-hover:var(--mp-violet-hover);--accent-soft:var(--mp-violet-soft);\n  --accent-text:var(--mp-violet-text);--on-accent:var(--mp-on-accent);\n  --ok:var(--mp-mint);--ok-soft:var(--mp-success-soft);\n  --warn:var(--mp-warning);--warn-soft:var(--mp-warning-soft);\n  --danger:var(--mp-coral);--danger-soft:var(--mp-error-soft);\n  --info:var(--mp-info);--info-soft:var(--mp-info-soft);--focus:var(--mp-focus);\n  --shadow-1:var(--mp-shadow);--shadow-2:var(--mp-shadow);--shadow-3:var(--mp-shadow);\n  --overlay:var(--mp-overlay);--code-bg:var(--mp-surface);\n  --r-sm:var(--mp-radius-field);--r:var(--mp-radius-button);--r-lg:var(--mp-radius-card);\n  --font:var(--mp-font-ui);--mono:ui-monospace,"SF Mono",Menlo,Consolas,monospace;\nposition:fixed;inset:0;z-index:100;background:var(--mp-overlay);overflow:auto;display:flex;align-items:center;flex-direction:column;padding:32px 16px}\n.mp-account-window[hidden]{display:none}\n.mp-account-window *{box-sizing:border-box}\n.mp-account-window button,.mp-account-window input{font:inherit}\n.mp-account-window h2,.mp-account-window h3,.mp-account-window p{margin:0}\n.mp-account-window .ico{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round;flex:none}\n.mp-account-window .ico-lg{width:20px;height:20px}\n.mp-account-window .spinner{width:16px;height:16px;border-radius:50%;border:2px solid currentColor;border-right-color:transparent;animation:spin .7s linear infinite;display:inline-block}\n.mp-account-window .field{display:flex;flex-direction:column;gap:6px;min-width:0}\n.mp-account-window .help{font-size:12.5px;color:var(--muted)}\n.mp-account-window .switch{display:inline-flex;align-items:center;gap:10px;cursor:pointer}\n.mp-account-window .switch input{appearance:none;width:34px;height:20px;border-radius:999px;background:var(--border-strong);position:relative;margin:0;cursor:pointer;transition:background .15s;flex:none}\n.mp-account-window .switch input::after{content:"";position:absolute;top:2px;left:2px;width:16px;height:16px;border-radius:50%;background:var(--mp-text);transition:transform .15s}\n.mp-account-window .switch input:checked{background:var(--ok)}\n.mp-account-window .switch input:checked::after{transform:translateX(14px)}\n.mp-account-window .switch input:focus-visible{box-shadow:var(--focus)}\n.badge{display:inline-flex;align-items:center;gap:5px;height:22px;padding:0 8px;border-radius:999px;font-size:12px;font-weight:500;background:var(--surface-2);color:var(--text-2);white-space:nowrap;border:1px solid transparent}\n.badge::before{content:"";width:6px;height:6px;border-radius:50%;background:currentColor;display:none}\n.badge.dot::before{display:block}\n.badge.ok{background:var(--ok-soft);color:var(--ok)}\n.badge.warn{background:var(--warn-soft);color:var(--warn)}\n.badge.danger{background:var(--danger-soft);color:var(--danger)}\n.badge.info{background:var(--info-soft);color:var(--info)}\n.badge.accent{background:var(--accent-soft);color:var(--accent-text)}\n.badge.outline{background:none;border-color:var(--border-strong)}\n.badge.mono{font-family:var(--mono);font-size:11px;border-radius:5px}\n.skeleton{height:12px;border-radius:4px;background:linear-gradient(90deg,var(--surface-2),var(--surface-3),var(--surface-2));background-size:200% 100%;animation:shimmer 1.2s infinite}\n.alert{display:flex;gap:10px;padding:12px 14px;border-radius:var(--r);background:var(--info-soft);color:var(--text);border:1px solid color-mix(in srgb,var(--info) 25%,transparent)}\n.alert .ico{color:var(--info);margin-top:2px}\n.alert.warn{background:var(--warn-soft);border-color:color-mix(in srgb,var(--warn) 30%,transparent)}\n.alert.warn .ico{color:var(--warn)}\n.alert.danger{background:var(--danger-soft);border-color:color-mix(in srgb,var(--danger) 30%,transparent)}\n.alert.danger .ico{color:var(--danger)}\n.alert.ok{background:var(--ok-soft);border-color:color-mix(in srgb,var(--ok) 30%,transparent)}\n.alert.ok .ico{color:var(--ok)}\n.alert b{display:block;margin-bottom:2px}\n.acw{width:100%;max-width:400px;min-width:0;background:var(--surface);color:var(--text);border:1px solid var(--border);border-radius:16px;box-shadow:var(--shadow-2);display:flex;flex-direction:column;font:14px/1.45 var(--font);overflow-wrap:anywhere}\n.acw *:focus-visible{outline:none;box-shadow:var(--focus)}\n.acw-top{display:flex;align-items:center;gap:8px;padding:12px 12px 4px 16px;min-height:60px}\n.acw-top .grow{flex:1;min-width:0}\n.acw-logo{font-family:var(--mp-font-display);display:flex;align-items:center;gap:8px;font-weight:600;font-size:15px}\n.acw-logo svg{width:28px;height:28px;border-radius:7px;flex:none}\n\n.acw-logo [data-part=icon]{width:28px;height:28px;border-radius:7px;flex:none}\n.acw-top h2{font-family:var(--mp-font-display);font-size:17px;flex:1;min-width:0}\n.acw-top [data-part=account-back]{color:var(--accent-text);padding:0 10px 0 6px}\n.acw-body{padding:8px 16px 16px;display:flex;flex-direction:column;gap:14px}\n.acw-foot{display:flex;justify-content:center;gap:16px;flex-wrap:wrap;padding:4px 16px 16px;font-size:12px}\n.acw .acw-logo{font-weight:600}.acw .acw-logo svg{width:28px;height:28px}\n.acw .acw-logo [data-part=icon]{width:28px;height:28px}\n.acw-foot a{color:var(--muted);text-decoration:underline;text-underline-offset:2px}\n\n.acw-head{display:flex;flex-direction:column;align-items:center;gap:8px;text-align:center;padding-top:4px}\n.acw-ava{width:80px;height:80px;border-radius:50%;display:grid;place-items:center;background:var(--accent);color:var(--on-accent);font-size:28px;font-weight:600;box-shadow:0 0 0 4px var(--surface),0 0 0 5px var(--accent-soft)}\n.acw-ava.guest{background:var(--surface-3);color:var(--muted)}\n.acw-ava .ico{width:36px;height:36px}\n.acw-nick{font-family:var(--mp-font-display);font-size:20px;font-weight:600;letter-spacing:-.01em}\n\n.acw-card .ri{width:40px;height:40px;border-radius:10px;display:grid;place-items:center;background:var(--accent-soft);color:var(--accent-text);flex:none}\n\n.acw-about{display:flex;align-items:center;gap:8px;padding:8px 8px 8px 12px;border-radius:var(--r);background:var(--surface-2);font-size:12.5px;color:var(--muted);flex-wrap:wrap}\n.acw-about span{flex:1;min-width:0}\n.acw-about code{color:var(--text);font-weight:600}\n.acw-about .mp-button{color:var(--accent-text)}\n.acw-copied{color:var(--ok);font-weight:500;display:inline-flex;gap:4px;align-items:center;min-height:36px;padding:0 8px}\n\n.acw-sec{display:flex;flex-direction:column;gap:6px}\n.acw-sec>h2,.acw-sec>h3{font-size:11px;font-weight:600;color:var(--muted);text-transform:uppercase;letter-spacing:.07em;padding:4px 2px 2px}\n.acw-list{display:flex;flex-direction:column;margin:0;padding:0;list-style:none;border:1px solid var(--border);border-radius:var(--r-lg)}\n.acw-list>li{display:flex;align-items:center;gap:12px;min-height:64px;padding:8px 12px}\n.acw-list>li+li{border-top:1px solid var(--border)}\n.acw-list .rt{flex:1;min-width:0;display:flex;flex-direction:column;gap:1px}\n.acw-list .rt b{font-weight:600}\n.acw-list .rt small{color:var(--muted);font-size:12.5px;font-variant-numeric:tabular-nums}\n.acw-playing{height:28px}\n.acw-loading{display:flex;justify-content:center;align-items:center;gap:8px;color:var(--muted);font-size:13px;padding:6px 0}\n.acw-skel{display:flex;align-items:center;gap:12px;min-height:64px;padding:8px 12px}\n.acw-skel .sq{width:44px;height:44px;border-radius:10px;flex:none}\n.acw-skel .ln{display:flex;flex-direction:column;gap:6px;flex:1}\n\n.acw-set{display:flex;align-items:center;gap:12px;min-height:56px;padding:8px 12px}\n.acw-set .rt{flex:1;min-width:0;display:flex;flex-direction:column}\n.acw-set .rt small{color:var(--muted);font-size:12.5px}\n.acw-set .rt b{font-weight:600}\n.acw-set .switch{cursor:not-allowed;opacity:.55}\n.acw-actions{display:flex;flex-direction:column;gap:8px}\n\n.acw-center{display:flex;flex-direction:column;align-items:center;text-align:center;gap:10px;padding:12px 4px 4px}\n.acw-center p{color:var(--muted);max-width:34ch;margin:0}\n.acw-bigico{width:64px;height:64px;border-radius:16px;display:grid;place-items:center;background:var(--accent-soft);color:var(--accent-text)}\n.acw-bigico .ico{width:30px;height:30px}\n.acw-bigico.ok{background:var(--ok-soft);color:var(--ok)}\n.acw-bigico.danger{background:var(--danger-soft);color:var(--danger)}\n.acw-bigico.warn{background:var(--warn-soft);color:var(--warn)}\n.acw-bullets{display:flex;flex-direction:column;gap:8px;margin:0;padding:0;list-style:none;text-align:left;width:100%}\n.acw-bullets li{display:flex;gap:10px;align-items:center;padding:10px 12px;border-radius:var(--r);background:var(--surface-2);font-size:13.5px}\n.acw-bullets .ico{color:var(--accent-text)}\n\n.acw-card{display:flex;align-items:center;gap:12px;padding:10px 12px;border:1px solid var(--border);border-radius:var(--r-lg);text-align:left;width:100%}\n.acw-card .acw-ava{width:40px;height:40px;font-size:15px;box-shadow:none}\n.acw-card .rt{display:flex;flex-direction:column;min-width:0}\n.acw-card .rt small{color:var(--muted);font-size:12.5px}\n.acw-card .acw-amount{font-size:22px;font-weight:700;color:var(--accent-text);font-variant-numeric:tabular-nums}\n.acw-nickrow{display:flex;gap:8px}\n.acw .is-invalid .mp-input{border-color:var(--danger)}\n.acw-status{font-size:13px;display:flex;gap:6px;align-items:center;min-height:20px}\n.acw-status.ok{color:var(--ok)}\n.acw-status.err{color:var(--danger)}\n.acw-status.wait{color:var(--muted)}\n.acw .alert{font-size:13px}\n\n\n.acw{margin:auto;flex:none}.acw-title{font-family:var(--mp-font-display);padding:0 16px;font-size:17px}.acw-ava img{width:100%;height:100%;object-fit:cover;border-radius:50%}\n.acw-set+.acw-set{border-top:1px solid var(--border)}\n.acw .acw-logo{font-weight:600}.acw .acw-logo svg{width:28px;height:28px}\n.acw .acw-logo [data-part=icon]{width:28px;height:28px}\n.acw-foot a{color:var(--muted)}.acw-foot{margin-top:auto}\n.acw-skel .sq{background:var(--surface-3)}.acw-skel .ln{background:var(--surface-3);height:14px;border-radius:6px}\n.acw-loading .spinner{opacity:0;animation:spin .7s linear infinite,account-spinner 0s .2s forwards}\n@keyframes account-spinner{to{opacity:1}}\n@keyframes spin{to{transform:rotate(360deg)}}\n@media(max-width:600px){.mp-account-window{padding:0}.acw{max-width:100%;min-height:100%;border:0;border-radius:0;margin:0}}\n';
